const body = $input.first().json.body || {};
const errors = [];

const email = String(body.email || '').trim().toLowerCase();
const message = String(body.message || '').trim();
const externalId = String(body.ticket_id || '').trim();

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('invalid email');
if (message.length < 3) errors.push('message too short');
if (message.length > 5000) errors.push('message too long');

if (errors.length) {
  return [{ json: { valid: false, errors } }];
}

// remove control characters and collapse extra whitespace
const normalized = message
  .replace(/[\u0000-\u001F]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    valid: true,
    external_id: externalId || 'T-' + Date.now(),
    email,
    name: body.name || null,
    raw_message: message,
    normalized_message: normalized
  }
}];

