const raw = $input.first().json.candidates[0].content.parts[0].text;
const c = JSON.parse(raw);

const clamp = (n) => Math.min(5, Math.max(1, Number(n) || 1));

return [{
  json: {
    ticket_id: $('Create a row').first().json.id,
    intent: c.intent,
    sentiment: c.sentiment,
    urgency: clamp(c.urgency),
    frustration: clamp(c.frustration),
    needs_order_data: !!c.needs_order_data,
    order_id: c.order_id || null,
    model_version: $input.first().json.modelVersion || 'unknown'
  }
}];

const cls = $('Parse Classification').first().json;
const input = $('Code').first().json;

const order = $('Get Order').isExecuted ? $('Get Order').first().json : {};
const customer = $('Get Customer').isExecuted ? $('Get Customer').first().json : {};

const orderFound = !!order.id;
const hasCustomer = !!customer.id;
const verified = orderFound && hasCustomer && order.customer_id === customer.id;

return [{
  json: {
    ticket_id: cls.ticket_id,
    email: input.email,
    message: input.normalized_message,
    classification: {
      intent: cls.intent,
      sentiment: cls.sentiment,
      urgency: cls.urgency,
      frustration: cls.frustration,
      order_id: cls.order_id
    },
    customer: hasCustomer ? { name: customer.name, tier: customer.tier } : null,
    order_found: orderFound,
    order_verified: verified,
    order: verified ? {
      id: order.id,
      status: order.status,
      total: order.total,
      tracking_number: order.tracking_number,
      placed_at: order.placed_at,
      delivered_at: order.delivered_at
    } : null
  }
}];

const base = $('Build Context').first().json;

const kb = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id)
  .map(r => ({
    id: r.id,
    document: r.document,
    content: r.content,
    similarity: Number(Number(r.similarity).toFixed(3))
  }));

return [{
  json: {
    ...base,
    kb_results: kb,
    kb_found: kb.length > 0,
    top_similarity: kb.length ? kb[0].similarity : 0
  }
}];

