const base = $('Parse Reply').first().json;
const raw = $input.first().json.candidates[0].content.parts[0].text;
const j = JSON.parse(raw);

const clamp01 = (n) => Math.min(1, Math.max(0, Number(n) || 0));
const grounded = clamp01(j.groundedness);
const judgeConf = clamp01(j.confidence);

// The system never trusts the AI's confidence alone
let confidence = Math.min(judgeConf, grounded);
if (!base.draft.can_answer) confidence = Math.min(confidence, 0.4);
if (!j.policy_ok || !j.tone_ok) confidence = Math.min(confidence, 0.3);
if (!base.kb_found && !base.order_verified) confidence = Math.min(confidence, 0.4);

return [{
  json: {
    ...base,
    evaluation: {
      groundedness: grounded,
      policy_ok: !!j.policy_ok,
      tone_ok: !!j.tone_ok,
      judge_confidence: judgeConf,
      final_confidence: Number(confidence.toFixed(2)),
      issues: j.issues || 'none'
    }
  }
}];

const t = $('Parse Judge').first().json;
const c = t.classification;
const ev = t.evaluation;
const msg = (t.message || '').toLowerCase();

// Thresholds. Later these will come from the config table.
const T = { auto_resolve: 0.85, approval: 0.60, refund_limit: 100 };
const critical = ['lawyer','sue','legal action','chargeback','fraud','police','scam'];

let action, rule, priority = 'normal';
const reasons = [];

if (critical.some(k => msg.includes(k)) || c.intent === 'legal_or_safety') {
  action = 'escalate'; rule = 'critical_keyword'; priority = 'critical';
  reasons.push('Legal, fraud or safety language detected');
} else if (c.frustration >= 4 && c.urgency >= 4) {
  action = 'escalate'; rule = 'angry_and_urgent'; priority = 'high';
  reasons.push('High frustration (' + c.frustration + ') and high urgency (' + c.urgency + ')');
} else if (c.order_id && !t.order_verified) {
  action = 'escalate'; rule = 'order_not_verified';
  reasons.push('Order ' + c.order_id + ' not found or does not belong to this customer');
} else if (c.intent === 'refund' && t.order && Number(t.order.total) > T.refund_limit) {
  action = 'escalate'; rule = 'refund_above_limit'; priority = 'high';
  reasons.push('Refund of $' + t.order.total + ' exceeds the $' + T.refund_limit + ' limit and needs manager approval');
} else if (!ev.policy_ok || !ev.tone_ok) {
  action = 'escalate'; rule = 'failed_quality_check';
  reasons.push('The self-check flagged the draft: ' + ev.issues);
} else if (!t.draft.can_answer) {
  action = 'clarify'; rule = 'insufficient_information';
  reasons.push('Not enough information to answer; asking the customer to clarify');
} else if (ev.final_confidence >= T.auto_resolve && ev.groundedness >= 0.8) {
  action = 'auto_resolve'; rule = 'high_confidence';
  reasons.push('Confidence ' + ev.final_confidence + ' with grounded answer');
} else if (ev.final_confidence >= T.approval) {
  action = 'draft_for_approval'; rule = 'medium_confidence';
  reasons.push('Confidence ' + ev.final_confidence + ' is below the auto-resolve threshold; a human should review');
} else {
  action = 'escalate'; rule = 'low_confidence';
  reasons.push('Confidence ' + ev.final_confidence + ' is too low');
}

const slaHours = { critical: 1, high: 4, normal: 24 }[priority];
const sla_due = new Date(Date.now() + slaHours * 3600 * 1000).toISOString();

const status = { auto_resolve: 'auto_resolved', draft_for_approval: 'pending_approval', escalate: 'escalated', clarify: 'clarification_needed' }[action];

const summary = [
  'Customer: ' + (t.customer ? t.customer.name : t.email) + (t.customer && t.customer.tier === 'vip' ? ' (VIP)' : ''),
  'Intent: ' + c.intent + ' | Urgency ' + c.urgency + '/5 | Frustration ' + c.frustration + '/5',
  'Message: ' + t.message,
  t.order ? 'Order ' + t.order.id + ': ' + t.order.status + ', $' + t.order.total : 'No verified order data',
  'Why escalated: ' + reasons.join('; '),
  'Draft reply (not sent): ' + t.draft.reply
].join('\n');

return [{
  json: {
    ...t,
    decision: {
      action, rule, priority, status, reasons, sla_due, summary,
      reasons_pg: '{' + reasons.map(r => JSON.stringify(r)).join(',') + '}',
      thresholds: T
    }
  }
}];

const t = $('Decision Engine').first().json;

const usage = (name) => {
  try {
    const u = $(name).first().json.usageMetadata || {};
    return { tin: u.promptTokenCount || 0, tout: u.candidatesTokenCount || 0 };
  } catch (e) { return { tin: 0, tout: 0 }; }
};

const row = (step, output, node) => {
  const u = node ? usage(node) : { tin: 0, tout: 0 };
  return { json: {
    ticket_id: t.ticket_id,
    step,
    output: JSON.stringify(output),
    tokens_in: u.tin,
    tokens_out: u.tout
  }};
};

return [
  row('classification', t.classification, 'Gemini Classify'),
  row('order_lookup', { order_found: t.order_found, order_verified: t.order_verified, order_id: t.classification.order_id }),
  row('kb_retrieval', { found: t.kb_found, top_similarity: t.top_similarity, chunks: (t.kb_results || []).map(k => ({ id: k.id, document: k.document, similarity: k.similarity })) }),
  row('reply_generation', { can_answer: t.draft.can_answer, cited_kb_ids: t.draft.cited_kb_ids, used_order_data: t.draft.used_order_data }, 'Generate Reply'),
  row('self_evaluation', t.evaluation, 'Judge Reply'),
  row('decision', { action: t.decision.action, rule: t.decision.rule, priority: t.decision.priority, reasons: t.decision.reasons })
];

