const ticketId = $('Create a row').first().json.id;
const input = $('Code').first().json;
const err = $input.first().json.error || 'Both AI models failed';

const summary = [
  'Customer: ' + input.email,
  'Message: ' + input.normalized_message,
  'Why escalated: The AI service was unavailable (' + (typeof err === 'string' ? err : JSON.stringify(err)).slice(0, 200) + ')',
  'No AI analysis was possible. Please handle this ticket manually.'
].join('\n');

return [{
  json: {
    ticket_id: ticketId,
    status: 'escalated',
    priority: 'high',
    summary,
    sla_due: new Date(Date.now() + 4 * 3600 * 1000).toISOString()
  }
}];
